}

void *memcpy(void *dest, const void *src, size_t count) /* <=== memcpy */ 
{
	char *tmp = dest;
	const char *s = src;

	while (count--)
		*tmp++ = *s++;
	return dest;
}

static inline int test_bit(unsigned long nr, const volatile unsigned long *ptr) /* <=== test_bit */ 
{
	const volatile unsigned char *addr;

	addr = ((const volatile unsigned char *)ptr);
	addr += (nr ^ (BITS_PER_LONG - 8)) >> 3;
	return (*addr >> (nr & 7)) & 1;
}

static inline u32 __get_unaligned_le32(const u8 *p) /* <=== __get_unaligned_le32 */ 
{
	return p[0] | p[1] << 8 | p[2] << 16 | p[3] << 24;
}

static inline u32 get_unaligned_le32(const void *p) /* <=== get_unaligned_le32 */ 
